import{_ as t,o,c as a,a2 as r}from"./chunks/framework.hwbV7reR.js";const u=JSON.parse('{"title":"Архитектура","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1791695486000}'),d={name:"architecture.md"};function i(c,e,l,n,p,s){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="архитектура" tabindex="-1">Архитектура <a class="header-anchor" href="#архитектура" aria-label="Permalink to &quot;Архитектура&quot;">​</a></h1><p>Оркестратор — самостоятельный модульный сервис. Backend заказчика решает, имеет ли пользователь доступ, резервирует слот и передаёт device_id и срок. Оркестратор управляет техническим назначением. Он не хранит пароли пользователей или платежи.</p><h2 id="карта-кода" tabindex="-1">Карта кода <a class="header-anchor" href="#карта-кода" aria-label="Permalink to &quot;Карта кода&quot;">​</a></h2><ul><li><code>bootstrap.py</code> собирает настройки, журнал, реестр, агент и драйверы.</li><li><code>domain/</code> содержит типы узлов, конфигураций, версий и ошибки.</li><li><code>application/execution.py</code> определяет общий бюджет прикладной операции; infrastructure использует его для ожиданий HTTP и блокировок.</li><li><code>application/telemetry.py</code> задаёт порт наблюдения и контекст корреляции; <code>infrastructure/observability.py</code> реализует JSON-события и Prometheus.</li><li><code>application/</code> содержит сценарии выдачи, отзыва, переключения, восстановления, управления узлами и коротких разрешений. <code>ports.py</code> задаёт контракты драйвера и lease transport; <code>repository_ports.py</code> — узкие интерфейсы журналов и хранилища секретов.</li><li><code>interfaces/http/</code> проверяет служебную авторизацию и преобразует вход/выход v1/v2.</li><li><code>interfaces/cli/</code> разбирает команды и приватные файлы оператора.</li><li><code>infrastructure/drivers/</code> содержит общий NodeHTTP, рабочий драйвер Amnezia-agent и экспериментальный адаптер TrustTunnel, не включённый в bootstrap.</li><li><code>infrastructure/sqlite/</code> владеет журналом, транзакциями, миграциями и блокировками.</li><li><code>config/</code> задаёт чистые модели настроек и политики. Загрузка файлов, секретов и сохранённого реестра находится в <code>infrastructure/settings.py</code>; сборка — в bootstrap.</li><li><code>infrastructure/systemd.py</code> управляет фиксированным набором служб без shell.</li></ul><p>Пакет <code>orchestrator/</code> остаётся в корне, чтобы существующие source releases и systemd entry points продолжали работать. <code>pyproject.toml</code> позволяет собрать wheel и установить CLI обычным pip. Перенос в <code>src/</code> сам по себе не улучшает границы, поэтому не требует миграции всех установленных путей.</p><h2 id="управление" tabindex="-1">Управление <a class="header-anchor" href="#управление" aria-label="Permalink to &quot;Управление&quot;">​</a></h2><p>Локальный CLI вызывает сценарии работы с узлами и использует общие межпроцессные блокировки. Запускается от того же системного пользователя, что служба. Админка сайта не управляет реестром или таймаутами. Административный HTTP API удалён. Обычный backend API работает независимо от наличия какой-либо админки.</p><h2 id="постоянное-состояние" tabindex="-1">Постоянное состояние <a class="header-anchor" href="#постоянное-состояние" aria-label="Permalink to &quot;Постоянное состояние&quot;">​</a></h2><p>SQLite содержит назначения, ревизии, незавершённые переключения, реестр серверов, разрешения и отложенный отзыв. Конфигурации туннелей и приватные VPN-ключи не сохраняются: только digest документа. Секреты агентов лежат в отдельных 0600-файлах.</p><p>Миграции собраны в одном модуле; сохранены прежние таблицы и их семантика. Прикладные сценарии работают через <code>Journal</code>, <code>SwitchJournal</code>, <code>LeaseJournal</code> и <code>InventoryJournal</code>. SQL находится только в инфраструктуре. Репозитории возвращают типизированные записи, а не соединения SQLite или курсоры.</p><p><code>SwitchRepository.complete</code> одной транзакцией меняет назначение и завершает переключение; резервирование цели учитывает остальные незавершённые операции. Сценарий удерживает прежнюю межпроцессную блокировку через <code>Journal.lock</code> вокруг локальных записей и обращения к узлу. Извлечение SQL не сокращает область блокировки. Время выдачи lease сохраняется до сетевого запроса; неизвестный результат не разрешает досрочно считать предыдущий доступ отозванным.</p><p>Версия схемы и порядок обновления описаны в <a href="./compatibility.html">совместимости</a>. Миграции сохраняют назначения, ключи повторяемости и незавершённые операции.</p><h2 id="гарантии-жизненного-цикла" tabindex="-1">Гарантии жизненного цикла <a class="header-anchor" href="#гарантии-жизненного-цикла" aria-label="Permalink to &quot;Гарантии жизненного цикла&quot;">​</a></h2><p>Одна операция имеет стабильную идентичность. Потеря ответа не разрешает создать другое назначение. Отзыв источника должен быть подтверждён или обеспечен проверенным механизмом ограниченного разрешения. Незавершённая операция закреплена за целевым узлом и восстанавливается после перезапуска. Нельзя произвольно выбрать третий сервер после таймаута и оставить неизвестное состояние на втором.</p><p>Добавление TrustTunnel требует реального драйвера с теми же гарантиями, собственной схемы конфигурации и тестов; имя в enum не делает протокол доступным.</p><h2 id="границы-этого-выпуска" tabindex="-1">Границы этого выпуска <a class="header-anchor" href="#границы-этого-выпуска" aria-label="Permalink to &quot;Границы этого выпуска&quot;">​</a></h2><p>Форматы v1/v2 не меняются. Не добавлены автоматические speed tests, пользовательская геолокация, многоарендность, новый 202 API или цепочки перебора нескольких серверов. Число автоматических попыток в нативном приложении остаётся его политикой. Вынесены только реально действующие настройки; неиспользуемых переключателей нет.</p><p>Старый лабораторный runtime и его 32 теста удалены. Рабочие тесты с закреплённым агентом сохранены; добавлены проверки CLI, пустой установки, политики и реестра.</p><h2 id="направление-зависимостеи" tabindex="-1">Направление зависимостей <a class="header-anchor" href="#направление-зависимостеи" aria-label="Permalink to &quot;Направление зависимостей&quot;">​</a></h2><p>Целевые правила фиксируются в <code>contracts/architecture.json</code> и проверяются командой <code>python scripts/check_architecture.py</code>. Проверка читает AST исходников, не запускает приложение и не загружает настройки или секреты.</p><table tabindex="0"><thead><tr><th>Слой</th><th>Разрешённые внутренние зависимости</th></tr></thead><tbody><tr><td>domain</td><td>Только domain; Pydantic разрешён для существующих моделей контрактов</td></tr><tr><td>application/ports, repository_ports, telemetry и execution</td><td>domain и другие определения ports</td></tr><tr><td>application</td><td>domain, ports, application, модели config/policy</td></tr><tr><td>config/policy</td><td>Только собственные модели политики</td></tr><tr><td>config</td><td>config/policy, domain и собственные модули конфигурации</td></tr><tr><td>infrastructure</td><td>domain, ports, config/policy и собственные реализации</td></tr><tr><td>interfaces/http</td><td>application, ports, domain, version и HTTP-модули</td></tr><tr><td>interfaces/cli</td><td>Прикладные операции, bootstrap, конфигурация, инфраструктура и CLI-модули</td></tr><tr><td>bootstrap</td><td>Собирает конкретные реализации и HTTP-приложение</td></tr><tr><td>version</td><td>Не зависит от остальных runtime-модулей</td></tr></tbody></table><p>CLI сейчас совмещает адаптацию команд и локальные операции установки, резервного копирования и systemd. Поэтому его доступ к инфраструктуре явно разрешён. HTTP обработчик такого доступа не имеет. Доменные модели и прикладной слой не импортируют HTTP/SQL-фреймворки. Policy-модели используют Pydantic; бизнес-сценарии от него не зависят.</p><p>Совместимые корневые модули перечислены отдельно. Они служат входом для старых установок; импортировать их из новых слоёв в обход правил нельзя. Новые модули в корне нужно явно классифицировать. Проверяются абсолютные, относительные, локальные и TYPE_CHECKING-импорты. Прямые вызовы <strong>import</strong>/importlib.import_module запрещены: динамические плагины сейчас не часть контракта.</p><p>Это статическая проверка объявленных зависимостей. Она не анализирует произвольное исполнение Python, SQL-строки, вызовы через переданные объекты или циклы внутри слоя и не является песочницей безопасности. Сохранение транзакций проверяется отдельно сценариями жизненного цикла.</p><h2 id="проверяемые-границы" tabindex="-1">Проверяемые границы <a class="header-anchor" href="#проверяемые-границы" aria-label="Permalink to &quot;Проверяемые границы&quot;">​</a></h2><p>Этап 4 устранил все 20 исключений первого этапа: <code>exceptions</code> теперь пуст. Новые зависимости проверяются по общим правилам; расширять список разрешений для обхода ошибки запрещено. Отдельный тест не допускает прямых вызовов SQL и открытия базы в application.</p><p><code>bootstrap.build_gateway</code> связывает журнал, драйверы, lease transports и ресурс закрытия HTTP-пула. <code>build_registry</code> передаёт хранилище файлов секретов через <code>Credentials</code>. Прикладной сценарий не создаёт AgentAPI и не читает ключ с диска. CLI читает входной файл до вызова сценария управления узлом.</p><p><code>LeaseTransport</code> переводит проверенное состояние агента в <code>LeaseObservation</code> и принимает <code>LeaseGrant</code>. Прикладное управление lease не знает HTTP-путей, JSON-полей или версии Amnezia-agent. Реализация Amnezia находится в <code>infrastructure/drivers/amnezia_leases.py</code>; новый протокол получает свой адаптер. Отсутствующий адаптер не даёт молча включить lease.</p><p><code>domain/records.py</code> определяет записи журналов и результаты драйвера. Mypy проверяет доменные модели, порты, реестры драйверов, SQLite-реализации, файловое хранилище секретов и два адаптера Amnezia. <code>scripts/check_types.py</code> проверяет соответствие конкретных реализаций портам. Это покрытие границ, не строгая типизация всего проекта.</p><p>Модели RenewRequest/ReplaceRequest/DeviceOperation используются и при HTTP-декодировании, и при генерации OpenAPI. Прежние маршруты и статусы ошибок сохраняются.</p><h2 id="сценарии-и-контракт-изменении" tabindex="-1">Сценарии и контракт изменений <a class="header-anchor" href="#сценарии-и-контракт-изменении" aria-label="Permalink to &quot;Сценарии и контракт изменений&quot;">​</a></h2><ul><li><a href="./lifecycle.html">Идентификаторы, состояния и гарантии жизненного цикла</a>.</li><li><a href="./compatibility.html">Версии, обновления и совместимость</a>.</li><li><a href="./security.html">Границы доверия и секретные данные</a>.</li></ul><p>Панель просмотра запускается отдельным процессом <code>panel</code>: HTTP-интерфейс зависит от порта <code>PanelReader</code>, SQLite-реализация открывает согласованный read-only снимок. Bootstrap не создаёт сервис выдачи туннелей, не загружает секреты агентов и не запускает миграции. Безопасные события API/worker поступают через ограниченный файловый EventTail. В браузер передаются только модели <code>domain/panel.py</code>. Клиентский backend API не становится административным; ключ панели отдельный. Опциональный режим <code>--manage</code> использует <code>application/administration.py</code> вместе с CLI. Порты OperatorJournal и PolicyEditor скрывают отдельный SQLite-аудит и атомарную запись настроек. Намерение фиксируется до команды; неизвестный исход требует сверки. Основная схема VPN-журнала не меняется. <a href="./panel.html">Запуск и контракт</a>. TrustTunnel следует после модернизации: второй драйвер должен подтвердить независимость этих границ на практике.</p>',33)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
